import bundledData from './kanaData.json';

// 원격 단어 데이터 URL (GitHub Pages). 이 파일만 업데이트하면 앱 재배포 없이 단어가 갱신된다.
export const DATA_URL = 'https://beios.github.io/hirakata/kana-data.json';

const CACHE_KEY = 'kanaDataCache';

// 앱에 번들된 기본(오프라인 폴백) 데이터
export const defaultData = bundledData;

export const shuffle = (array) => {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
};

// 데이터 구조 유효성 검사
const isValid = (data) =>
  data &&
  Array.isArray(data.categories) &&
  data.categories.length > 0 &&
  data.categories.every(
    (c) => c && c.id && Array.isArray(c.words) && c.words.length > 0
  );

/**
 * 단어 데이터를 불러온다.
 * 1) 원격(GitHub Pages)에서 최신 데이터 fetch → 성공 시 캐시에 저장 후 사용
 * 2) 실패 시 캐시된 데이터 사용
 * 3) 그것도 없으면 앱에 번들된 기본 데이터 사용
 */
export async function loadQuizData() {
  try {
    const res = await fetch(DATA_URL, { cache: 'no-store' });
    if (res.ok) {
      const data = await res.json();
      if (isValid(data)) {
        try {
          localStorage.setItem(CACHE_KEY, JSON.stringify(data));
        } catch (e) {
          /* 저장 실패는 무시 */
        }
        return data;
      }
    }
  } catch (e) {
    // 네트워크 오류 등: 폴백으로 진행
  }

  try {
    const cached = localStorage.getItem(CACHE_KEY);
    if (cached) {
      const parsed = JSON.parse(cached);
      if (isValid(parsed)) return parsed;
    }
  } catch (e) {
    /* 캐시 파싱 실패: 번들 데이터로 진행 */
  }

  return defaultData;
}
