// 로컬 테스트를 위한 모의 서비스
class MockService {
    constructor() {
        this.mockUser = {
            uid: 'mock-user-id',
            email: 'test@example.com',
            displayName: '테스트 사용자'
        };
        
        this.mockData = {
            quizHistory: [],
            progress: {},
            sessions: []
        };
    }

    // 모의 인증 상태
    getMockAuthState() {
        return {
            user: this.mockUser,
            isAuthenticated: true
        };
    }

    // 모의 퀴즈 히스토리
    getMockQuizHistory() {
        return [
            {
                id: '1',
                date: new Date().toISOString(),
                score: 85,
                totalQuestions: 10,
                correctAnswers: 8,
                timeSpent: 120,
                characterType: 'hiragana'
            },
            {
                id: '2',
                date: new Date(Date.now() - 86400000).toISOString(),
                score: 92,
                totalQuestions: 10,
                correctAnswers: 9,
                timeSpent: 95,
                characterType: 'katakana'
            }
        ];
    }

    // 모의 진행 상황
    getMockProgress() {
        return {
            hiragana: {
                mastered: 15,
                learning: 8,
                notStarted: 27
            },
            katakana: {
                mastered: 12,
                learning: 10,
                notStarted: 28
            }
        };
    }

    // 모의 세션 데이터
    getMockSessions() {
        return [
            {
                id: '1',
                startTime: new Date(Date.now() - 3600000).toISOString(),
                endTime: new Date().toISOString(),
                duration: 3600,
                charactersPracticed: 25,
                accuracy: 88
            }
        ];
    }

    // 모의 데이터 저장
    saveMockData(data) {
        console.log('모의 데이터 저장:', data);
        return Promise.resolve({ success: true });
    }

    // 모의 데이터 로드
    loadMockData() {
        return Promise.resolve({
            quizHistory: this.getMockQuizHistory(),
            progress: this.getMockProgress(),
            sessions: this.getMockSessions()
        });
    }
}

const mockService = new MockService();
export default mockService; 