import React, { useState, useEffect } from 'react';
import { Trash2, CheckCircle2 } from 'lucide-react';
import { auth } from '../firebase/config';
import { clearQuizHistory, loadSyncedData } from '../services/syncService';

const QuizHistory = () => {
  const [isSyncing, setIsSyncing] = useState(false);
  const [results, setResults] = useState([]);

  const loadResults = () => {
    try {
      setResults(JSON.parse(localStorage.getItem('quizResults') || '[]'));
    } catch (e) {
      setResults([]);
    }
  };

  useEffect(() => {
    const syncHistory = async () => {
      if (auth.currentUser) {
        setIsSyncing(true);
        await loadSyncedData(auth.currentUser.uid);
        setIsSyncing(false);
      }
      loadResults();
    };
    syncHistory();
  }, []);

  const formatDate = (timestamp) => new Date(timestamp).toLocaleString('ko-KR');

  const handleClearHistory = async () => {
    if (!window.confirm('모든 학습 기록을 삭제할까요?\n이 작업은 되돌릴 수 없습니다.')) return;

    setIsSyncing(true);
    const ok = await clearQuizHistory(auth.currentUser?.uid);
    setIsSyncing(false);

    if (ok) {
      setResults([]);
    } else {
      window.alert('기록 삭제에 실패했습니다. 네트워크 연결을 확인해 주세요.');
      loadResults();
    }
  };

  return (
    <div className="w-full mt-6">
      <div className="flex justify-between items-center mb-4 px-1">
        <h2 className="text-sm font-black text-indigo-400 uppercase tracking-widest">학습 기록</h2>
        <div className="flex items-center gap-2">
          {isSyncing && (
            <span className="text-[10px] font-bold text-slate-500 uppercase animate-pulse">동기화 중...</span>
          )}
          {results.length > 0 && (
            <button
              onClick={handleClearHistory}
              className="flex items-center gap-1 py-1.5 px-2.5 rounded-lg bg-slate-900 border border-slate-800 text-slate-500 text-[10px] font-black uppercase tracking-wider hover:text-rose-400 active:scale-95 transition-all"
            >
              <Trash2 size={12} /> Clear
            </button>
          )}
        </div>
      </div>

      {results.length === 0 ? (
        <div className="py-16 text-center text-slate-600 font-bold text-sm">아직 학습 기록이 없어요.</div>
      ) : (
        <ul className="space-y-2">
          {results.map((result) => {
            const total = result.total || 0;
            const score = result.score || 0;
            const percent = total ? Math.round((score / total) * 100) : 0;
            return (
              <li
                key={result.timestamp}
                className="flex items-center justify-between p-3 bg-slate-900 rounded-2xl border border-slate-800"
              >
                <div className="min-w-0">
                  <div className="text-sm font-black text-white truncate">
                    {result.categoryLabel || result.category}
                  </div>
                  <div className="text-[10px] text-slate-500 font-bold mt-0.5">
                    {formatDate(result.timestamp)}
                  </div>
                </div>
                <div className="flex items-center gap-1.5 text-right whitespace-nowrap">
                  <CheckCircle2 size={16} className="text-emerald-400" />
                  <span className="text-sm font-black text-emerald-400">
                    {score}/{total}
                  </span>
                  <span className="text-[10px] font-bold text-slate-500">({percent}%)</span>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
};

export default QuizHistory;
