import { initializeApp } from 'firebase/app';
import { getAuth, GoogleAuthProvider } from 'firebase/auth';
import { getFirestore } from 'firebase/firestore';
import { getAnalytics, isSupported } from 'firebase/analytics';

// Your web app's Firebase configuration
// For Firebase JS SDK v7.20.0 and later, measurementId is optional
const firebaseConfig = {
    apiKey: process.env.REACT_APP_FIREBASE_API_KEY,
    authDomain: "hirakata-web.firebaseapp.com",
    projectId: "hirakata-web",
    storageBucket: "hirakata-web.firebasestorage.app",
    messagingSenderId: "871875082055",
    appId: process.env.REACT_APP_FIREBASE_APP_ID,
    measurementId: "G-JK2E5DT7XQ"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Analytics는 브라우저 환경에서만 지원되므로(네이티브 WebView 등에서 크래시 방지)
// 지원 여부를 확인한 뒤 초기화한다.
export let analytics = null;
isSupported()
  .then((supported) => {
    if (supported) analytics = getAnalytics(app);
  })
  .catch(() => {
    /* 미지원 환경: analytics 미사용 */
  });

// Initialize Firebase services
export const auth = getAuth(app);
export const googleProvider = new GoogleAuthProvider();
export const db = getFirestore(app);

