import { signOut } from 'firebase/auth';
import { auth } from '../firebase/config';

const SESSION_TIMEOUT = 10 * 60 * 1000; // 10분 (밀리초)
const SESSION_KEY = 'userSession';

class SessionService {
    constructor() {
        this.timeoutId = null;
        this.activityListeners = [];
        this.isActive = false;
        
        // 페이지 로드 시 기존 세션 확인
        this.checkExistingSession();
    }

    // 기존 세션 확인
    checkExistingSession() {
        const sessionData = localStorage.getItem(SESSION_KEY);
        if (!sessionData) return;

        const { timestamp, isActive } = JSON.parse(sessionData);
        if (!isActive) return;

        const now = Date.now();
        const timeDiff = now - timestamp;

        if (timeDiff >= SESSION_TIMEOUT) {
            // 세션이 만료된 경우 자동 로그아웃
            this.endSession();
        } else {
            // 세션이 유효한 경우 타이머 재시작
            this.isActive = true;
            this.setupActivityListeners();
            this.startTimeout();
            console.log('기존 세션이 복원되었습니다.');
        }
    }

    // 세션 시작
    startSession(userId) {
        if (!userId) return;
        
        this.isActive = true;
        this.updateSessionTimestamp();
        this.setupActivityListeners();
        this.startTimeout();
        
        console.log('세션이 시작되었습니다. 10분 후 자동 로그아웃됩니다.');
    }

    // 세션 종료
    endSession() {
        this.isActive = false;
        this.clearTimeout();
        this.removeActivityListeners();
        this.clearSessionData();
        
        // Firebase에서 로그아웃
        signOut(auth).catch(error => {
            console.error('세션 타임아웃 로그아웃 에러:', error);
        });
        
        console.log('세션이 만료되어 자동 로그아웃되었습니다.');
    }

    // 세션 갱신 (사용자 활동 시)
    refreshSession() {
        if (!this.isActive) return;
        
        this.updateSessionTimestamp();
        this.restartTimeout();
    }

    // 세션 타임스탬프 업데이트
    updateSessionTimestamp() {
        const sessionData = {
            timestamp: Date.now(),
            isActive: true
        };
        localStorage.setItem(SESSION_KEY, JSON.stringify(sessionData));
    }

    // 세션 데이터 확인
    checkSession() {
        const sessionData = localStorage.getItem(SESSION_KEY);
        if (!sessionData) return false;

        const { timestamp, isActive } = JSON.parse(sessionData);
        if (!isActive) return false;

        const now = Date.now();
        const timeDiff = now - timestamp;

        if (timeDiff >= SESSION_TIMEOUT) {
            this.endSession();
            return false;
        }

        return true;
    }

    // 타임아웃 시작
    startTimeout() {
        this.clearTimeout();
        this.timeoutId = setTimeout(() => {
            this.endSession();
        }, SESSION_TIMEOUT);
    }

    // 타임아웃 재시작
    restartTimeout() {
        this.startTimeout();
    }

    // 타임아웃 클리어
    clearTimeout() {
        if (this.timeoutId) {
            clearTimeout(this.timeoutId);
            this.timeoutId = null;
        }
    }

    // 사용자 활동 감지 리스너 설정
    setupActivityListeners() {
        const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'click'];
        
        this.activityListeners = events.map(event => {
            const listener = () => this.refreshSession();
            document.addEventListener(event, listener, true);
            return { event, listener };
        });
    }

    // 활동 감지 리스너 제거
    removeActivityListeners() {
        this.activityListeners.forEach(({ event, listener }) => {
            document.removeEventListener(event, listener, true);
        });
        this.activityListeners = [];
    }

    // 세션 데이터 클리어
    clearSessionData() {
        localStorage.removeItem(SESSION_KEY);
    }

    // 남은 세션 시간 확인 (초 단위)
    getRemainingTime() {
        const sessionData = localStorage.getItem(SESSION_KEY);
        if (!sessionData) return 0;

        const { timestamp } = JSON.parse(sessionData);
        const now = Date.now();
        const timeDiff = now - timestamp;
        const remaining = Math.max(0, SESSION_TIMEOUT - timeDiff);
        
        return Math.ceil(remaining / 1000); // 초 단위로 반환
    }

    // 세션 상태 확인
    isSessionActive() {
        return this.isActive && this.checkSession();
    }
}

// 싱글톤 인스턴스 생성
const sessionService = new SessionService();
export default sessionService; 