import React from 'react';
import { Capacitor } from '@capacitor/core';
import { FirebaseAuthentication } from '@capacitor-firebase/authentication';
import {
  signInWithPopup,
  signInWithCredential,
  signOut,
  GoogleAuthProvider,
} from 'firebase/auth';
import { LogOut } from 'lucide-react';
import { auth, googleProvider } from '../firebase/config';
import sessionService from '../services/sessionService';
import mockService from '../services/mockService';

const GoogleIcon = ({ size = 18 }) => (
  <svg width={size} height={size} viewBox="0 0 48 48" aria-hidden="true">
    <path
      fill="#FFC107"
      d="M43.611 20.083H42V20H24v8h11.303c-1.649 4.657-6.08 8-11.303 8-6.627 0-12-5.373-12-12s5.373-12 12-12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 12.955 4 4 12.955 4 24s8.955 20 20 20 20-8.955 20-20c0-1.341-.138-2.65-.389-3.917z"
    />
    <path
      fill="#FF3D00"
      d="M6.306 14.691l6.571 4.819C14.655 15.108 18.961 12 24 12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 16.318 4 9.656 8.337 6.306 14.691z"
    />
    <path
      fill="#4CAF50"
      d="M24 44c5.166 0 9.86-1.977 13.409-5.192l-6.19-5.238C29.211 35.091 26.715 36 24 36c-5.202 0-9.619-3.317-11.283-7.946l-6.522 5.025C9.505 39.556 16.227 44 24 44z"
    />
    <path
      fill="#1976D2"
      d="M43.611 20.083H42V20H24v8h11.303c-.792 2.237-2.231 4.166-4.087 5.571.001-.001.002-.001.003-.002l6.19 5.238C36.971 39.205 44 34 44 24c0-1.341-.138-2.65-.389-3.917z"
    />
  </svg>
);

function Auth({ user, onMockLogin }) {
  const isDevelopment = process.env.NODE_ENV === 'development';

  const handleGoogleLogin = async () => {
    try {
      if (Capacitor.isNativePlatform()) {
        // 네이티브: 구글 네이티브 로그인 → 받은 idToken으로 JS SDK 인증
        // useCredentialManager:false → One Tap 대신 레거시 계정 선택창 사용(자격증명 매칭 실패 회피)
        const result = await FirebaseAuthentication.signInWithGoogle({
          useCredentialManager: false,
        });
        const idToken = result.credential?.idToken;
        const accessToken = result.credential?.accessToken;
        if (!idToken) {
          throw new Error('idToken을 받지 못했습니다. (SHA-1/웹 클라이언트 설정 확인 필요)');
        }
        const credential = GoogleAuthProvider.credential(idToken, accessToken);
        await signInWithCredential(auth, credential);
      } else {
        // 웹: 팝업 방식
        await signInWithPopup(auth, googleProvider);
      }
    } catch (error) {
      console.error('로그인 에러:', error.code, error.message);
      // 네이티브 디버깅을 위해 에러를 화면에 노출 (원인 파악 후 제거 가능)
      window.alert(`로그인 오류\ncode: ${error.code || '-'}\nmessage: ${error.message || error}`);
    }
  };

  const handleMockLogin = () => {
    const mockUser = mockService.getMockAuthState().user;
    sessionService.startSession(mockUser.uid);
    if (onMockLogin) onMockLogin(mockUser);
  };

  const handleLogout = async () => {
    try {
      sessionService.endSession();
      if (user && user.uid === 'mock-user-id') {
        if (onMockLogin) onMockLogin(null);
      } else {
        if (Capacitor.isNativePlatform()) {
          await FirebaseAuthentication.signOut();
        }
        await signOut(auth);
      }
    } catch (error) {
      console.error('로그아웃 에러:', error);
    }
  };

  if (user) {
    return (
      <button
        onClick={handleLogout}
        title="로그아웃"
        className="flex items-center gap-1.5 pl-1 pr-2 py-1 rounded-full bg-slate-900 border border-slate-800 active:scale-95 transition-all shrink-0"
      >
        <img
          src={user.photoURL || `${process.env.PUBLIC_URL}/logo192.png`}
          alt={user.displayName || 'user'}
          className="w-7 h-7 rounded-full border border-indigo-500 object-cover"
        />
        <LogOut size={14} className="text-slate-400" />
      </button>
    );
  }

  return (
    <div className="flex items-center gap-1.5 shrink-0">
      <button
        onClick={handleGoogleLogin}
        title="구글 로그인"
        className="w-9 h-9 flex items-center justify-center rounded-full bg-white shadow active:scale-95 transition-all"
      >
        <GoogleIcon size={18} />
      </button>
      {isDevelopment && (
        <button
          onClick={handleMockLogin}
          title="테스트 로그인"
          className="px-1.5 py-1 rounded-md bg-slate-800 border border-slate-700 text-[9px] font-black text-slate-400 uppercase active:scale-95 transition-all"
        >
          Test
        </button>
      )}
    </div>
  );
}

export default Auth;
