import { Capacitor } from '@capacitor/core';

// Google 공식 "테스트" 광고 단위 ID.
// 실제 배포 전에 AdMob 콘솔에서 발급받은 실제 ID로 교체해야 한다.
// (테스트 ID를 그대로 배포하면 수익이 발생하지 않고, 실제 ID로 직접 클릭 테스트하면 계정 정지 위험이 있으므로 개발 중에는 반드시 테스트 ID 사용)
const TEST_BANNER_ANDROID = 'ca-app-pub-3940256099942544/6300978111';

// 실제 배포용 배너 ID로 교체할 위치 (현재는 null → 테스트 ID 사용)
const PROD_BANNER_ANDROID = null;

const isNative = Capacitor.isNativePlatform();

let initialized = false;

export async function initAds() {
  if (!isNative || initialized) return;
  try {
    const { AdMob } = await import('@capacitor-community/admob');
    await AdMob.initialize({});
    initialized = true;
  } catch (e) {
    console.warn('AdMob 초기화 실패', e);
  }
}

export async function showBanner() {
  if (!isNative) return;
  try {
    await initAds();
    const { AdMob, BannerAdPosition, BannerAdSize } = await import('@capacitor-community/admob');
    await AdMob.showBanner({
      adId: PROD_BANNER_ANDROID || TEST_BANNER_ANDROID,
      adSize: BannerAdSize.ADAPTIVE_BANNER,
      position: BannerAdPosition.BOTTOM_CENTER,
      margin: 0,
    });
  } catch (e) {
    console.warn('배너 광고 표시 실패', e);
  }
}

export async function hideBanner() {
  if (!isNative) return;
  try {
    const { AdMob } = await import('@capacitor-community/admob');
    await AdMob.hideBanner();
  } catch (e) {
    /* 무시 */
  }
}
